int: n = 6;
int: E = 9;
array[1..E, 1..2] of int: graph = [
   | 3, 1
   | 3, 6
   | 3, 4
   | 6, 4
   | 6, 1
   | 1, 5
   | 1, 4
   | 4, 5
   | 4, 2
];

array[1..n] of var 1..n: colors;

// neighbouring countries must have different colours
constraint
  forall(e in 1..E) (
    let { i = graph[e,1], j = graph[e,2] } in
      colors[i] != colors[j]
  );

// minimize the number of colours used
var 1..n: num_colors = max(colors);
solve minimize num_colors;

// output as JSON
output [
  "{",
    "\"colors\": [" ++
    join(",", [ show(colors[i]) | i in 1..n ]) ++
    "]",
  "}"
];
