include "globals.mzn";

/*
  We number:
    Children:   1=Bernice, 2=Carl, 3=Debby, 4=Sammy, 5=Ted
    Ages:       1=3yrs,  2=5yrs,   3=7yrs,   4=8yrs,   5=10yrs
    Countries:  1=Ethiopia, 2=Kazakhstan, 3=Lithuania, 4=Morocco, 5=Yemen
    Stories:    1=BurningBush, 2=Captivity, 3=MosesYouth, 4=Passover, 5=TenCmdmts
*/

/* decision variables */
array[1..5] of var 1..5: age_of_child;     % age_of_child[c] = age‐code of child c
array[1..5] of var 1..5: country_of_child; % country_of_child[c] = country‐code of child c
array[1..5] of var 1..5: story_of_child;   % story_of_child[c] = story‐code of child c

/* inverse: child_for_age[a] = child whose age‐code is a */
array[1..5] of var 1..5: child_for_age;

constraint
  all_different(age_of_child) /\
  all_different(country_of_child) /\
  all_different(story_of_child) /\
  inverse(age_of_child, child_for_age);

/* helper vars for indexing special facts */
var 1..5: cPassover;    constraint story_of_child[cPassover] = 4;
var 1..5: cMoses;       constraint story_of_child[cMoses]    = 3;
var 1..5: cYemen;       constraint country_of_child[cYemen]   = 5;
var 1..5: cEthiopia;    constraint country_of_child[cEthiopia]= 1;
var 1..5: cMorocco;     constraint country_of_child[cMorocco] = 4;

/* 1. Debby(=3) is from Lithuania(=3) */
constraint country_of_child[3] = 3;

/* 2. Passover‐teller is 2 years older than Bernice(=1) */
/*    in our age‐codes a +2‐year jump = +1 index */
constraint age_of_child[cPassover] = age_of_child[1] + 1;

/* 3. Yemen‐child younger than Ethiopia‐child */
constraint age_of_child[cYemen] < age_of_child[cEthiopia];

/* 4. Morocco‐child is 3 years older than Ted(=5) */
/*    3‐year jump = +2 index */
constraint age_of_child[cMorocco] = age_of_child[5] + 2;

/* 5. Sammy(=4) is 3 years older than the MosesYouth storyteller */
constraint age_of_child[4] = age_of_child[cMoses] + 2;

solve satisfy;

/* print arrays of codes, all length 5 */
output [
  "{",
  join(",", [
    "\"ages\": [" ++ join(",", [ show(age_of_child[i])     | i in 1..5 ]) ++ "]",
    "\"children\": [" ++ join(",", [ show(child_for_age[i])    | i in 1..5 ]) ++ "]",
    "\"countries\": [" ++ join(",", [ show(country_of_child[i]) | i in 1..5 ]) ++ "]",
    "\"stories\": [" ++ join(",", [ show(story_of_child[i])    | i in 1..5 ]) ++ "]"
  ]),
  "}"
];
