include "globals.mzn";

int: n_cows = 25;
set of int: Cows = 1..n_cows;
set of int: Sons = 0..4;

/* number of cows each son should get */
array[Sons] of int: num_cows = [7,6,5,4,3];

/* total milk and per‐son milk */
int: total_milk = sum(c in Cows)(c);
constraint total_milk mod card(Sons) = 0;
int: per_son_milk = total_milk div card(Sons);

/* assignment of each cow to a son 0..4 */
array[Cows] of var Sons: cow_assignments;

/* enforce each son gets exactly num_cows[s] cows */
constraint
  global_cardinality(cow_assignments, [s | s in Sons], num_cows);

/* enforce each son gets exactly per_son_milk kilograms */
constraint
  forall(s in Sons) (
    sum(c in Cows)(c * (cow_assignments[c] == s)) = per_son_milk
  );

solve satisfy;

/* JSON output */
output [
  "{",
    "\"cow_assignments\": ["
    ++ join(",", [ show(cow_assignments[c]) | c in Cows ])
    ++ "]",
  "}"
];
```

