include "globals.mzn";

int: num_people = 8;
set of int: P = 1..num_people;
array[P] of set of P: compatible = [
    {2,3},
    {1,6},
    {1,4,7},
    {2},
    {2},
    {5},
    {8},
    {3}
];

array[P, P] of var bool: transplants;

// enforce compatibility: if not compatible, no transplant
constraint
  forall(i, j in P) (
    if j in compatible[i] then
      true
    else
      transplants[i,j] = false
    endif
  );

// each person donates at most one kidney
constraint
  forall(i in P) (
    sum(j in P)(transplants[i,j]) <= 1
  );

// each person receives at most one kidney
constraint
  forall(j in P) (
    sum(i in P)(transplants[i,j]) <= 1
  );

// anyone who gives must also receive: outdeg[i] <= indeg[i]
constraint
  forall(i in P) (
    sum(j in P)(transplants[i,j])
    <=
    sum(k in P)(transplants[k,i])
  );

// maximize number of recipients
solve maximize
  sum(j in P)(sum(i in P)(transplants[i,j]));

// output as JSON
output [
  "{",
  "\"transplants\": [",
    join(",",
      [ "[" ++
          join(",", [ show(bool2int(transplants[i,j])) | j in P ])
        ++ "]"
      | i in P
      ]
    ),
  "]",
  "}"
];
```

