include "globals.mzn";

int: n = 8;  % number of nodes
array[1..n] of array[int] of int: adjacency_list = [
    [2, 3, 7],
    [1, 4, 8],
    [1, 4, 5],
    [2, 3, 6],
    [3, 6, 7],
    [4, 5, 8],
    [1, 5, 8],
    [2, 6, 7]
];

% Decision: nodes[i] = true if node i is in the independent set
array[1..n] of var bool: nodes;

% 1) Independence: no two adjacent nodes both selected
constraint
  forall(i in 1..n, j in adjacency_list[i]) (
    bool2int(nodes[i]) + bool2int(nodes[j]) <= 1
  );

% 2) Maximality: every unselected node must have at least one neighbor selected
constraint
  forall(i in 1..n) (
    bool2int(nodes[i]) + sum([ bool2int(nodes[j]) | j in adjacency_list[i] ]) >= 1
  );

solve satisfy;

% Output as JSON
output [
  "{",
    "\"nodes\": [" ++
      join(",",
           [ show(bool2int(nodes[i])) | i in 1..n ]
      )
      ++ "]",
  "}"
];
```

This model finds a maximal independent set of the given graph and prints an array `nodes` of 0/1 values indicating which vertices are included.

