% 13 people enter a room one at a time.
% 4 males (0), 9 females (1).
% At any prefix, the ratio females/males <= 7/3.
% If no males yet (males=0), then females must be 0 to keep ratio finite.

int: n = 13;
int: num_male = 4;
int: num_female = 9;

% Decision: sequence of entrants, 0=male, 1=female
array[1..n] of var 0..1: seq;

% Prefix sum of females
array[1..n] of var 0..n: f;

% Constraints
constraint
    % Exactly num_female ones in the sequence
    sum(seq) = num_female
;

% Define prefix sums f[i]
constraint
    f[1] = seq[1]
;
constraint
    forall(i in 2..n) (
        f[i] = f[i-1] + seq[i]
    )
;

% Enforce ratio: for each prefix i,
%   let males = i - f[i], then 3*f[i] <= 7*males
% This also forces f[i]==0 if males=0.
constraint
    forall(i in 1..n) (
        3 * f[i] <= 7 * (i - f[i])
    )
;

solve satisfy;

% Output the sequence as JSON
output [
    "{",
    "\"sequence\":[" ++ join(",", [ show(seq[i]) | i in 1..n ]) ++ "]",
    "}"
];
```

