// Problem data
int: num_jobs = 3;
array[1..num_jobs] of int: n_tasks = [3, 3, 2];
int: max_tasks = 3;
int: num_tasks = sum(n_tasks);
int: num_machines = 3;

// Flattened task data: for each task t=1..num_tasks
//   machine[t]  in 1..num_machines
//   duration[t] in ℕ
array[1..num_tasks] of int: machine  = [ 1,2,3,  1,3,2,  2,3 ];
array[1..num_tasks] of int: duration = [ 3,2,2,  2,1,4,  4,3 ];

// idx[j,t] = global task‐index of the t‐th operation of job j (0 if none)
array[1..num_jobs, 1..max_tasks] of int: idx =
  [| 1, 2, 3
   ; 4, 5, 6
   ; 7, 8, 0 |];

// an upper bound on the schedule length
int: horizon = sum(duration);

// decision vars: start time of each task, and its end time
array[1..num_tasks] of var 0..horizon: start;
array[1..num_tasks] of var 0..horizon: end_t;

// link end times
constraint
  forall(t in 1..num_tasks) (
    end_t[t] = start[t] + duration[t]
  );

// precedence in each job
constraint
  forall(j in 1..num_jobs, t in 1..n_tasks[j]-1) (
    let { int: t1 = idx[j,t], t2 = idx[j,t+1] }
    in start[t1] + duration[t1] <= start[t2]
  );

// no overlap on each machine via cumulative (each task consumes 1 unit, capacity=1)
constraint
  forall(m in 1..num_machines) (
    let {
      set of int: Tm = { t | t in 1..num_tasks where machine[t] == m }
    } in
    cumulative(
      [ start[t]     | t in Tm ],
      [ duration[t]  | t in Tm ],
      [ 1            | t in Tm ],
      1
    )
  );

// makespan = maximum of all end times
var int: makespan = max(end_t);

// objective
solve minimize makespan;

// JSON output
output [
  "{",
    "\"makespan\": " ++ show(makespan),
  "}"
];
