% Mario Problem: Orienteering / Prize‐collecting path from MarioHouse to LuigiHouse
% Maximize collected gold under fuel constraint. 
% Successor array s[i] gives the next house after i in the route; if i has no successor, s[i]=i.

int: nbHouses = 15;
set of int: H = 1..nbHouses;

% Data
int: MarioHouse = 1;
int: LuigiHouse = 2;
int: fuelMax = 2000;

array[H,H] of int: conso = 
 [
  |  0,221,274,808, 13,677,670,921,943,969, 13, 18,217, 86,322
  |  0,  0,702, 83,813,679,906,246,335,529,719,528,451,242,712
  |274,702,  0,127,110, 72,835,  5,161,430,686,664,799,523, 73
  |808, 83,127,  0,717, 80, 31, 71,683,668,248,826,916,467,753
  | 13,813,110,717,  0,951,593,579,706,579,101,551,280,414,294
  |677,679, 72, 80,951,  0,262, 12,138,222,146,571,907,225,938
  |670,906,835, 31,593,262,  0,189,558, 27,287,977,226,454,501
  |921,246,  5, 71,579, 12,189,  0,504,221,483,226, 38,314,118
  |943,335,161,683,706,138,558,504,  0,949,393,721,267,167,420
  |969,529,430,668,579,222, 27,221,949,  0,757,747,980,589,528
  | 13,719,686,248,101,146,287,483,393,757,  0,633,334,492,859
  | 18,528,664,826,551,571,977,226,721,747,633,  0, 33,981,375
  |217,451,799,916,280,907,226, 38,267,980,334, 33,  0,824,491
  | 86,242,523,467,414,225,454,314,167,589,492,981,824,  0,143
  |322,712, 73,753,294,938,501,118,420,528,859,375,491,143,  0
 ];

array[H] of int: goldInHouse = 
  [  0,  0, 40, 67, 89, 50,  6, 19, 47, 68, 94, 86, 34, 14, 14 ];

% Decision variables
array[H,H] of var bool: x;      % x[i,j]=true iff we go from i to j
array[H]   of var 0..1: outdeg; % number of successors of i (0 or 1)
array[H]   of var 0..1: indeg;  % number of predecessors of i (0 or 1)
array[H]   of var 0..nbHouses: u; % MTZ ordering variables
array[H]   of var bool: visited;
var int: totalFuel = sum(i,j in H)( conso[i,j] * bool2int(x[i,j]) );
var int: totalGold = sum(i in H)( goldInHouse[i] * bool2int(visited[i]) );

% Define degrees
constraint
  forall(i in H) (
    outdeg[i] = sum(j in H)( bool2int(x[i,j]) )
  ) /\
  forall(j in H) (
    indeg[j] = sum(i in H)( bool2int(x[i,j]) )
  );

% No self‐loops
constraint forall(i in H)( x[i,i] = false );

% Start and end constraints
constraint outdeg[MarioHouse] = 1 /\ indeg[MarioHouse] = 0;
constraint outdeg[LuigiHouse] = 0 /\ indeg[LuigiHouse] = 1;

% Other houses: at most one in, at most one out
constraint
  forall(i in H diff {MarioHouse, LuigiHouse}) (
    outdeg[i] <= 1 /\
    indeg[i] <= 1
  );

% MTZ subtour‐elimination: if x[i,j]=1 then u[j] = u[i] + 1
constraint u[MarioHouse] = 0;
constraint
  forall(i,j in H where i != j) (
    u[i] + 1 <= u[j] + nbHouses * (1 - bool2int(x[i,j]))
  );

% Fuel constraint
constraint totalFuel <= fuelMax;

% Visited definition: MarioHouse is visited; others if indeg=1
constraint visited[MarioHouse] = true;
constraint
  forall(i in H diff {MarioHouse}) (
    visited[i] = (indeg[i] = 1)
  );

% Objective: maximize gold collected
solve maximize totalGold;

% Define successor array s[i]
array[H] of var 1..nbHouses: s;
constraint
  forall(i in H) (
    s[i] = 
      if outdeg[i] = 1 
      then sum(j in H)( j * bool2int(x[i,j]) )
      else i
  );

% Output the successor list
output [
  "[",
  join(", ", [ show(s[i]) | i in H ]),
  "]"
];
```

Explanation of main parts:
- We use a Boolean matrix `x[i,j]` to indicate travel from house i to j.
- Degree constraints ensure a single path from MarioHouse to LuigiHouse, no node visited more than once.
- MTZ (Miller–Tucker–Zemlin) ordering `u[i]` eliminates subtours.
- Fuel consumption is summed over chosen arcs and bounded by `fuelMax`.
- We mark a house `visited[i]` if it has exactly one predecessor in the path (except the start).
- The objective maximizes the sum of `goldInHouse[i]` over visited houses.
- Finally, we build `s[i]`, the successor of house i (or `i` itself if it has no successor), and print it as a list of 15 integers.

