% Other houses: at most one in, at most one out
constraint
  forall(i in H diff {MarioHouse, LuigiHouse}) (
    outdeg[i] <= 1 /\
    indeg[i] <= 1
  );

% MTZ subtour‐elimination: if x[i,j]=1 then u[j] = u[i] + 1
constraint u[MarioHouse] = 0;
constraint
  forall(i,j in H where i != j) (
    u[i] + 1 <= u[j] + nbHouses * (1 - bool2int(x[i,j]))
  );

% Fuel constraint
constraint totalFuel <= fuelMax;

% Visited definition: MarioHouse is visited; others if indeg=1
constraint visited[MarioHouse] = true;
constraint
  forall(i in H diff {MarioHouse}) (
    visited[i] = (indeg[i] = 1)
  );

% Objective: maximize gold collected
solve maximize totalGold;

% Define successor array s[i]
array[H] of var 1..nbHouses: s;
constraint
  forall(i in H) (
    s[i] = 
      if outdeg[i] = 1 
      then sum(j in H)( j * bool2int(x[i,j]) )
      else i
  );

% Output the successor list
output [
  "[",
  join(", ", [ show(s[i]) | i in H ]),
  "]"
];
```

Explanation of main parts:
- We use a Boolean matrix `x[i,j]` to indicate travel from house i to j.
- Degree constraints ensure a single path from MarioHouse to LuigiHouse, no node visited more than once.
- MTZ (Miller–Tucker–Zemlin) ordering `u[i]` eliminates subtours.
- Fuel consumption is summed over chosen arcs and bounded by `fuelMax`.
- We mark a house `visited[i]` if it has exactly one predecessor in the path (except the start).
- The objective maximizes the sum of `goldInHouse[i]` over visited houses.
- Finally, we build `s[i]`, the successor of house i (or `i` itself if it has no successor), and print it as a list of 15 integers.

