int: T = 20;               % number of steps
int: N = 3;                % puzzle dimension
set of int: I = 1..N;
set of int: J = 1..N;

%--- input data -----------------------
array[I,J] of int: puzzle_start =
  array2d(I,J, [ 0,3,6,
                 2,4,8,
                 1,7,5 ]);

array[I,J] of int: puzzle_end =
  array2d(I,J, [ 1,2,3,
                 4,5,6,
                 7,8,0 ]);
%---------------------------------------

% board at each time 0..T
array[0..T, I, J] of var 0..8: board;

% coordinates of the empty tile (value 0) at each time
array[0..T] of var I: xe;
array[0..T] of var J: ye;

% initialise start and end configurations
constraint
  forall(i,j in I,J) (
    board[0,i,j] = puzzle_start[i,j]
  /\ board[T,i,j] = puzzle_end[i,j]
  );

% link empty-tile coordinates to board values at t=0 and t=T
constraint
  forall(i,j in I,J) (
    puzzle_start[i,j] = 0 -> (xe[0] = i /\ ye[0] = j)
  /\
    puzzle_end[i,j]   = 0 -> (xe[T] = i /\ ye[T] = j)
  );

% enforce that board[t, xe[t], ye[t]] is the empty tile
constraint forall(t in 0..T)(
  board[t, xe[t], ye[t]] = 0
);

% each board is a permutation of 0..8
constraint forall(t in 0..T)(
  all_different([ board[t,i,j] | i,j in I,J ])
);

% legal moves: empty moves to a neighbor
constraint forall(t in 1..T)(
  abs(xe[t] - xe[t-1]) + abs(ye[t] - ye[t-1]) = 1
);

% effect of move: swap empty with the neighbor tile
constraint forall(t in 1..T)(
  board[t, xe[t-1], ye[t-1]] = board[t-1, xe[t], ye[t]]
);

% all other tiles remain unchanged
constraint forall(t in 1..T, i,j in I,J)(
  if (i == xe[t-1] /\ j == ye[t-1])
  \/ (i == xe[t]   /\ j == ye[t])
  then
    true
  else
    board[t,i,j] = board[t-1,i,j]
  endif
);

solve satisfy;

% output the sequence of boards as JSON
output [
  "{",
  "\"steps\": [" ++
    join(",",
      [ "[" ++ join(",",
          [ "[" ++ join(",",
              [ show(board[t,i,j]) | j in J ]
            ) ++ "]"
            | i in I
          ]
        ) ++ "]"
        | t in 0..T
      ]
    )
  ++ "]",
  "}"
];
