int: n = 4;
array[1..n] of int: widths  = [3, 4, 2, 1];
array[1..n] of int: heights = [2, 3, 1, 4];

/* Upper‐bounds for the container dimensions */
int: UBx = sum(widths);
int: UBy = sum(heights);

/* Decision variables */
var 0..UBx: total_x;
var 0..UBy: total_y;
array[1..n] of var 0..UBx: pos_x;
array[1..n] of var 0..UBy: pos_y;

/* Each rectangle must lie inside the container */
constraint
  forall(i in 1..n) (
    pos_x[i] + widths[i]  <= total_x /\
    pos_y[i] + heights[i] <= total_y
  );

/* Non‐overlap constraint using global constraint */
constraint
  no_overlap_2d(
    [ pos_x[i] | i in 1..n ],
    widths,
    [ pos_y[i] | i in 1..n ],
    heights
  );

/* Minimize the area of the container */
var int: area;
constraint area = total_x * total_y;

solve minimize area;

/* JSON‐style output */
output [
  "{",
    join(",", [
      "\"pos_x\": [" ++ join(",", [ show(pos_x[i]) | i in 1..n ]) ++ "]",
      "\"pos_y\": [" ++ join(",", [ show(pos_y[i]) | i in 1..n ]) ++ "]",
      "\"total_x\": " ++ show(total_x),
      "\"total_y\": " ++ show(total_y)
    ]),
  "}"
];
