int: nResources = 2;
int: nJobs = 12;
set of int: JOBS = 0..nJobs-1;
set of int: RES = 1..nResources;

/-- Data --/
array[JOBS] of int: durations =
    [0,3,2,5,4,2,3,4,2,4,6,0];

array[JOBS, RES] of int: resource_needs =
    array2d(JOBS, RES,
      [ 0,0,  5,1,  0,4,  1,4,  1,3,  3,2,
        3,1,  2,4,  4,0,  5,2,  2,5,  0,0 ]);

array[RES] of int: resource_capacities = [6,8];

/-- Precedence successor links (0‐based) --/
int: nSucc = 18;
array[1..nSucc] of int: succ_i = 
    [0,0,0, 1,1, 2,2, 3,4,4, 5,5, 6,6, 7, 8,9,10];
array[1..nSucc] of int: succ_j = 
    [1,2,3, 4,5, 9,10,8,6,7, 9,10,8,9, 8,11,11,11];

/-- Time horizon upper bound --/
int: horizon = sum(durations);

/-- Decision variables --/
array[JOBS] of var 0..horizon: start_time;
var 0..horizon: makespan;

/-- Precedence constraints --/
constraint
  forall(k in 1..nSucc) (
    start_time[succ_i[k]] 
    + durations[succ_i[k]] 
    <= start_time[succ_j[k]]
  );

/-- Resource‐capacity constraints via cumulative for each resource --/
constraint
  forall(r in RES) (
    cumulative(
      start_time,
      [durations[j] | j in JOBS],
      [resource_needs[j,r] | j in JOBS],
      resource_capacities[r]
    )
  );

/-- Makespan definition and objective --/
constraint
  makespan = max([ start_time[j] + durations[j] | j in JOBS ]);

solve minimize makespan;

/-- JSON‐style output of the start times --/
output [
  "{",
    "\"start_time\": [" ++ join(",", [ show(start_time[j]) | j in JOBS ]) ++ "]",
  "}"
];
