% Wolf, Goat and Cabbage river crossing puzzle
% Number of stages (including initial and final)
int: stage;
int: num_stages = stage;

% Positions at each stage: 0 = starting shore, 1 = destination shore
array [1..num_stages] of var 0..1: wolf_pos;
array [1..num_stages] of var 0..1: goat_pos;
array [1..num_stages] of var 0..1: cabbage_pos;
array [1..num_stages] of var 0..1: boat_pos;

% Initial state: all on starting shore
constraint
  wolf_pos[1] = 0 /\
  goat_pos[1] = 0 /\
  cabbage_pos[1] = 0 /\
  boat_pos[1] = 0;

% Final state: all on destination shore
constraint
  wolf_pos[num_stages] = 1 /\
  goat_pos[num_stages] = 1 /\
  cabbage_pos[num_stages] = 1 /\
  boat_pos[num_stages] = 1;

% At each crossing (between stage s and s+1):
% 1) The boat must move (farmer always crosses).
% 2) At most one item (wolf, goat, or cabbage) may move with the boat.
constraint
  forall(s in 1..num_stages-1) (
    boat_pos[s] != boat_pos[s+1] /\
    let {
      % Differences indicate which items moved
      array[1..3] of var 0..1: diffs = [
        bool2int(wolf_pos[s]     != wolf_pos[s+1]),
        bool2int(goat_pos[s]     != goat_pos[s+1]),
        bool2int(cabbage_pos[s]  != cabbage_pos[s+1])
      ]
    } in
      sum(diffs) <= 1
  );

% Safety constraints at every stage:
% - Wolf and goat cannot be alone together without the boat.
% - Goat and cabbage cannot be alone together without the boat.
constraint
  forall(s in 1..num_stages) (
    (wolf_pos[s] != goat_pos[s] \/ boat_pos[s] = wolf_pos[s]) /\
    (goat_pos[s] != cabbage_pos[s] \/ boat_pos[s] = goat_pos[s])
  );

solve satisfy;

output [
  "{",
    join(",", [
      "\"wolf_pos\": [" ++ join(",", [show(wolf_pos[s])    | s in 1..num_stages]) ++ "]",
      "\"goat_pos\": [" ++ join(",", [show(goat_pos[s])    | s in 1..num_stages]) ++ "]",
      "\"cabbage_pos\": [" ++ join(",", [show(cabbage_pos[s])| s in 1..num_stages]) ++ "]",
      "\"boat_pos\": [" ++ join(",", [show(boat_pos[s])    | s in 1..num_stages]) ++ "]"
    ]),
  "}"
];
```

