% Number of marks on the Golomb ruler
int: size;

% An upper bound on the ruler length
int: max_len = size * size;

% Position of each mark: 0 = a[1] < a[2] < ... < a[size]
array[1..size] of var 0..max_len: a;
constraint a[1] = 0;
constraint forall(i in 1..size-1) (a[i] < a[i+1]);

% Differences matrix: diff[i,j] = a[j] - a[i] for i < j
array[1..size, 1..size] of var 0..max_len: diff;
constraint forall(i, j in 1..size where i < j) (
  diff[i,j] = a[j] - a[i]
);

% Flatten the upper‐triangle differences into a single array
int: nDiffs = size*(size-1) div 2;
array[1..nDiffs] of var 0..max_len: diffs = 
  [ diff[i,j] | i,j in 1..size where i < j ];

% All differences must be distinct
constraint alldifferent(diffs);

% Break the symmetry: first gap < last gap
constraint diff[1,2] < diff[size-1,size];

% The length of the ruler is the position of the last mark
var 0..max_len: length = a[size];

solve minimize length;

output [
  "{",
  "\"marks\": [" ++ join(", ", [ show(a[i]) | i in 1..size ]) ++ "],",
  "\"length\": " ++ show(length),
  "}"
];
```

