% All-Interval Series for n pitch-classes
int: n = 12;

% The series s[1..n] is a permutation of 0..n-1
array[1..n] of var 0..n-1: s;
constraint all_different(s);

% diffs[i] = |s[i+1] - s[i]|, must be a permutation of 1..n-1
array[1..n-1] of var 1..n-1: diffs;
constraint all_different(diffs);
constraint forall(i in 1..n-1)(
    diffs[i] = abs(s[i+1] - s[i])
);

