include "globals.mzn";

int: n_teams = 9;
int: n_days = 18;
set of int: Teams = 1..n_teams;
set of int: Days  = 1..n_days;

/* Helper to convert bool to int */
function int: b2i(bool: b) = if b then 1 else 0 endif;

/* Define special teams by index */
int: CLE = 1;
int: DUK = 2;
int: FSU = 3;
int: GT  = 4;
int: UMD = 5;
int: UNC = 6;
int: NCSt= 7;
int: UVA = 8;
int: WAK = 9;

/* Mirroring scheme */
array[1..9] of var 1..n_days: mirror1 = [
    1, 2, 3, 4, 5, 6, 7, 10, 11
];
array[1..9] of var 1..n_days: mirror2 = [
    8, 9, 12, 13, 14, 15, 16, 17, 18
];

/* Rival pairs (except FSU) */
array[1..4] of var Teams: rivA = [DUK, CLE, NCSt, UMD];
array[1..4] of var Teams: rivB = [UNC, GT, WAK, UVA];

/* Constrained pairs in days 11..18 */
array[1..4] of var Teams: conA = [WAK, WAK, GT, GT];
array[1..4] of var Teams: conB = [UNC, DUK, UNC, DUK];

/* Days sets */
set of int: Weekend    = { d | d in Days where d mod 2 = 0 };
set of int: FirstWknds = {2,4,6,8,10};
set of int: LastTwo    = {17,18};

/* Decision vars */
/* opponent[d,t]=0 means bye, else opponent day d of team t */
array[Days, Teams] of var 0..n_teams: opponent;
/* where[d,t] =  1 home, 0 bye, -1 away */
array[Days, Teams] of var -1..1: where;

/* Basic matching and bye constraints */
constraint
  forall(d in Days, t in Teams) (
    /* no self-play */
    opponent[d,t] != t
  ) /\
  forall(d in Days) (
    /* exactly one bye per day */
    sum(t in Teams)(b2i(opponent[d,t] = 0)) = 1
  ) /\
  forall(d in Days, t in Teams) (
    /* symmetry of matches */
    if opponent[d,t] > 0 then opponent[d, opponent[d,t]] = t else true endif
  ) /\
  forall(d in Days, t in Teams) (
    /* where matches opponent */
    (opponent[d,t] = 0 /\ where[d,t] = 0)
    \/
    (opponent[d,t] > 0 /\ where[d,t] != 0)
  );

/* Double round robin: each pair exactly twice, one home each */
constraint
  forall(i,j in Teams where i < j) (
    sum(d in Days)(b2i(opponent[d,i] = j)) = 2
    /\
    sum(d in Days)(b2i(opponent[d,i] = j /\ where[d,i] = 1)) = 1
  );

/* Mirroring */
constraint
  forall(k in 1..9, t in Teams) (
    let { int: d1 = mirror1[k], d2 = mirror2[k] } in
      opponent[d1,t] = opponent[d2,t]
      /\ where[d1,t] = - where[d2,t]
  );

/* No two final away games */
constraint
  forall(t in Teams) (
    not (where[17,t] = -1 /\ where[18,t] = -1)
  );

/* Home/Away/Bye pattern constraints */
constraint
  forall(t in Teams, d in 1..n_days-2) (
    sum(k in 0..2)(b2i(where[d+k,t] = -1)) <= 2   /* max 2 aways in a row */
  ) /\
  forall(t in Teams, d in 1..n_days-2) (
    sum(k in 0..2)(b2i(where[d+k,t] =  1)) <= 2   /* max 2 homes in a row */
  ) /\
  forall(t in Teams, d in 1..n_days-3) (
    sum(k in 0..3)(b2i(where[d+k,t] <= 0)) <= 3   /* max 3 away or byes */
  ) /\
  forall(t in Teams, d in 1..n_days-3) (
    sum(k in 0..3)(b2i(where[d+k,t] >= 0)) <= 4   /* max 4 home or byes */
  );

/* Weekend pattern */
constraint
  forall(t in Teams) (
    sum(d in Weekend)(b2i(where[d,t] =  1)) = 4
    /\
    sum(d in Weekend)(b2i(where[d,t] = -1)) = 4
    /\
    sum(d in Weekend)(b2i(where[d,t] =  0)) = 1
  );

/* First five weekends: at least 2 home or bye */
constraint
  forall(t in Teams) (
    sum(d in FirstWknds)(b2i(where[d,t] != -1)) >= 2
  );

/* Rival matches: in last day */
constraint
  forall(k in 1..4) (
    let { int: a = rivA[k], b = rivB[k] } in
    if opponent[18,a] != FSU /\ opponent[18,a] != 0
    /\ opponent[18,b] != FSU /\ opponent[18,b] != 0
    then opponent[18,a] = b endif
  );

/* Constrained matches in days 11..18 */
constraint
  forall(k in 1..4) (
    sum(d in 11..18)(b2i(opponent[d,conA[k]] = conB[k])) >= 1
  );

/* Opponent sequence constraints */
/* No two consecutive away vs UNC and Duke */
constraint
  forall(t in Teams, d in 1..n_days-1) (
    not (
      where[d,t] = -1 /\ where[d+1,t] = -1
      /\ (opponent[d,t]  = UNC \/ opponent[d,t]  = DUK)
      /\ (opponent[d+1,t] = UNC \/ opponent[d+1,t] = DUK)
      /\ opponent[d,t] != opponent[d+1,t]
    )
  );

/* No three consecutive against UNC,Duke,Wake in any order */
constraint
  forall(t in Teams, d in 1..n_days-2) (
    let {
      bool: bUNC  = or([opponent[d+i,t] = UNC  | i in 0..2]),
      bool: bDUK  = or([opponent[d+i,t] = DUK  | i in 0..2]),
      bool: bWAK  = or([opponent[d+i,t] = WAK  | i in 0..2])
    } in
      not (bUNC /\ bDUK /\ bWAK)
  );

/* Other specific constraints */
/* UNC-Duke on day 11 and day 18 */
constraint opponent[11,UNC] = DUK;
constraint opponent[18,UNC] = DUK;
/* UNC vs Clem on day 2 */
constraint opponent[2,UNC] = CLE;
/* Duke bye on day 16 */
constraint opponent[16,DUK] = 0;
/* Wake not home on day 17 */
constraint where[17,WAK] != 1;
/* Wake bye on day 1 */
constraint opponent[1,WAK] = 0;
/* Cannot play away on last day */
constraint forall(t in {CLE,DUK,UMD,WAK})(where[18,t] != -1);
/* Cannot play away on first day */
constraint forall(t in {CLE,FSU,GT,WAK})(where[1,t] != -1);
/* No bye on last day for FSU, NCSt */
constraint opponent[18,FSU] != 0 /\ opponent[18,NCSt] != 0;
/* No bye on first day for UNC */
constraint opponent[1,UNC] != 0;

/* Solve */
solve satisfy;

/* Output as JSON */
output [
  "{",
    "\"config\": [",
      join(",",
        [ "[" ++ join(",", [ show(opponent[d,t]) | t in Teams ]) ++ "]"
          | d in Days
        ]
      ),
    "],",
    "\"where\": [",
      join(",",
        [ "[" ++ join(",", [ show(where[d,t]) | t in Teams ]) ++ "]"
          | d in Days
        ]
      ),
    "]",
  "}"
];
