include "globals.mzn";

int: n_boats = 5;
int: n_periods = 4;
array[1..n_boats] of int: capacity = [6, 8, 12, 12, 12];
array[1..n_boats] of int: crew_size = [2, 2, 2, 2, 4];

set of int: Boats = 1..n_boats;
set of int: Periods = 1..n_periods;

% Decision: which boats are hosts
array[Boats] of var bool: is_host;

% visits[b,p] = the host boat that boat b visits in period p (for hosts they "visit" themselves)
array[Boats, Periods] of var Boats: visits;

% If b is host, it stays on itself; otherwise it cannot visit itself
constraint
  forall(b in Boats) (
    is_host[b] ->
      forall(p in Periods)( visits[b,p] = b )
    /\
    not is_host[b] ->
      forall(p in Periods)( visits[b,p] != b )
  );

% Every visit must go to a host
constraint
  forall(b in Boats, p in Periods) (
    is_host[ visits[b,p] ]
  );

% Capacity constraint: for each host h at each period p, host crew + all guest crews aboard ≤ capacity
constraint
  forall(h in Boats, p in Periods) (
    crew_size[h]
    +
    sum(b in Boats where b != h)(
      crew_size[b] * bool2int(visits[b,p] = h)
    )
    <= capacity[h]
  );

% A guest boat cannot revisit the same host twice
constraint
  forall(b in Boats where not is_host[b]) (
    all_different([ visits[b,p] | p in Periods ])
  );

% Any two boats meet at most once (i.e., they cannot visit the same host in more than one period)
constraint
  forall(b1, b2 in Boats where b1 < b2) (
    sum(p in Periods)( bool2int(visits[b1,p] = visits[b2,p]) ) <= 1
  );

% Objective: minimize number of hosts
var int: num_hosts = sum(b in Boats)( bool2int(is_host[b]) );
solve minimize num_hosts;

% JSON output of the is_host array and the visit schedule
output [
  "{",
    "\"is_host\": [" ++
      join(",", [ show(is_host[b]) | b in Boats ]) ++
    "],",
    "\"visits\": [" ++
      join(",", [
        "[" ++ join(",", [ show(visits[b,p]) | p in Periods ]) ++ "]"
        | b in Boats
      ]) ++
    "]",
  "}"
];
```

