include "globals.mzn";

int: n_teams;                   % Number of teams (must be even)
set of int: Teams = 0..n_teams-1;

% First‐leg weeks
int: n_weeks = n_teams - 1;
range Weeks1 = 1..n_weeks;
int: n_periods = n_teams div 2;
range Periods = 1..n_periods;

% Full tournament weeks (double round robin)
int: n_weeks_full = 2 * n_weeks;
range WeeksFull = 1..n_weeks_full;

% Decision variables for the first half
array[Weeks1, Periods] of var Teams: home1;
array[Weeks1, Periods] of var Teams: away1;

% Full‐tournament variables (home/away), built by repeating and swapping
array[WeeksFull, Periods] of var Teams: home;
array[WeeksFull, Periods] of var Teams: away;

% alias first‐leg into full; second‐leg is swap
constraint
  forall(w in WeeksFull, p in Periods) (
    if w <= n_weeks then
      home[w,p] = home1[w,p] /\
      away[w,p] = away1[w,p]
    else
      let { int: w2 = w - n_weeks } in
        home[w,p] = away1[w2,p] /\
        away[w,p] = home1[w2,p]
    endif
  );

% 1) No team plays itself in a match
constraint forall(w in Weeks1, p in Periods) (
  home1[w,p] != away1[w,p]
);

% 2) Every team plays exactly once each week (first half)
constraint
  forall(w in Weeks1, t in Teams) (
    sum(p in Periods)( if home1[w,p] = t then 1 else 0 endif
                   + if away1[w,p] = t then 1 else 0 endif )
    = 1
  );

% 3) Every pair meets exactly once in the first half
constraint
  forall(i, j in Teams where i < j) (
    sum(w in Weeks1, p in Periods)(
      if (home1[w,p] = i /\ away1[w,p] = j)
      \/ (home1[w,p] = j /\ away1[w,p] = i)
      then 1 else 0 endif
    ) = 1
  );

% 4) No team appears more than twice in the same period (first half)
constraint
  forall(p in Periods, t in Teams) (
    sum(w in Weeks1)(
      if home1[w,p] = t then 1 else 0 endif
    + if away1[w,p] = t then 1 else 0 endif
    ) <= 2
  );

solve satisfy;

% Output full double‐round schedule as JSON
output [
  "{",
    "\"home\": [",
      join(",",
        [ "[" ++ join(",", [ show(home[w,p]) | p in Periods ]) ++ "]"
          | w in WeeksFull
        ]
        ),"],",
    "\"away\": [",
      join(",",
        [ "[" ++ join(",", [ show(away[w,p]) | p in Periods ]) ++ "]"
          | w in WeeksFull
        ]
        ),"]",
  "}"
];

% Sample data
% To run with n_teams=8:
%    minizinc --data-file=data.dzn tournament.mzn
% where data.dzn contains: n_teams = 8;
