include "globals.mzn";

% Parameters for the BIBD
int: v = 9;    % number of objects (points)
int: b = 12;   % number of blocks
int: r = 4;    % each object occurs in r blocks
int: k = 3;    % each block contains k objects
int: l = 1;    % every pair of distinct objects occurs in exactly l blocks

% Incidence matrix: x[i,j] = true iff object i is in block j
array[1..v, 1..b] of var bool: x;

% Row sums = r
constraint
  forall(i in 1..v)(
    sum(j in 1..b)( bool2int(x[i,j]) ) = r
  );

% Column sums = k
constraint
  forall(j in 1..b)(
    sum(i in 1..v)( bool2int(x[i,j]) ) = k
  );

% Pairwise intersections = l
constraint
  forall(i, j in 1..v where i < j)(
    sum(c in 1..b)( bool2int(x[i,c]) * bool2int(x[j,c]) ) = l
  );

% Symmetry‐breaking: fix the first object's membership to the first r blocks
constraint forall(j in 1..r)( x[1,j] );
constraint forall(j in r+1..b)( not x[1,j] );

solve satisfy;

% Output the incidence matrix as JSON
output [
  "{",
    "\"matrix\": [",
      join(",",
        [ "[" ++
            join(",",
              [ show(bool2int(x[i,j])) | j in 1..b ]
            )
          ++ "]"
        | i in 1..v ]
      ),
    "]",
  "}"
];
```

