include "globals.mzn";

int: n = 8;             % number of words
int: L = 8;             % length of each word
set of int: ALPH = 1..4;  % 1=A, 2=C, 3=G, 4=T

% Letter names for output
array[1..4] of string: letter = ["A","C","G","T"];
% Watson–Crick complement map: A↔T, C↔G
array[1..4] of int: comp_map = [4,3,2,1];

% The words: w[i,j] is the j-th symbol of word i
array[1..n, 1..L] of var ALPH: w;

% Each word has exactly 4 symbols in {C,G} i.e. values 2 or 3
constraint
  forall(i in 1..n)(
    sum(j in 1..L)( bool2int(w[i,j] == 2) + bool2int(w[i,j] == 3) ) = 4
  );

% Hamming distance >=4 for each pair of distinct words
constraint
  forall(i,j in 1..n where i < j)(
    sum(k in 1..L)( bool2int(w[i,k] != w[j,k]) ) >= 4
  );

% Cross‐constraint: for all i,j, reverse(w[i]) vs. complement(w[j]) differ >=4
constraint
  forall(i,j in 1..n)(
    sum(k in 1..L)(
      bool2int(w[i, L-k+1] != comp_map[w[j,k]])
    ) >= 4
  );

% Symmetry breaking: enforce lex order on the words
constraint
  forall(i in 1..n-1)(
    lex_less([ w[i,k] | k in 1..L ], [ w[i+1,k] | k in 1..L ])
  );

solve satisfy;

output [
  "{",
    "\"words\": [" ++
      join(
        ",",
        [ "\"" ++
            join("", [ letter[w[i,j]] | j in 1..L ]) 
          ++ "\""
        | i in 1..n ]
      )
    ++ "]",
  "}"
];
