include "globals.mzn";

int: n = 9;                          % order of the Steiner triple system
int: num_blocks = n*(n-1) div 6;     % should be 12 when n=9
int: r = (n-1) div 2;                % each element occurs in r blocks (for BIBD property)

% incidence matrix: x[b,i] = true iff block b contains point i
array[1..num_blocks, 1..n] of var bool: x;

% each block has exactly 3 points
constraint
  forall(b in 1..num_blocks) (
    sum(i in 1..n)( bool2int(x[b,i]) ) = 3
  );

% each point appears in exactly r blocks
constraint
  forall(i in 1..n) (
    sum(b in 1..num_blocks)( bool2int(x[b,i]) ) = r
  );

% each pair of points is covered by exactly one block
constraint
  forall(i,j in 1..n where i < j) (
    sum(b in 1..num_blocks)(
      bool2int( x[b,i] /\ x[b,j] )
    ) = 1
  );

% symmetry‐breaking: lexicographically order the incidence‐rows
constraint
  forall(b in 1..num_blocks-1) (
    lex_less(x[b,], x[b+1,])
  );

solve satisfy;

% output the list of triples as a JSON array of arrays
output [
  "[",
    join(",", [
      "[" ++ join(",", [ show(i) | i in 1..n where x[b,i] ]) ++ "]"
    | b in 1..num_blocks ]),
  "]"
];
```

Explanation of the model:

1. We declare an `n×num_blocks` boolean incidence matrix `x[b,i]`.
2. We enforce each block `b` has exactly 3 points.
3. We enforce each point `i` appears in exactly `r = (n-1)/2` blocks.
4. We ensure every pair of distinct points `(i,j)` is contained in exactly one block.
5. To reduce symmetries, we lexicographically order the rows of `x`.
6. Finally we `solve satisfy` and print the solution as a JSON array of length `num_blocks`, each entry being a sorted triple.

