include "globals.mzn";

int: N = 10;  % number of vertices

% Decision variables
array[1..N,1..N] var bool: adj;     % adjacency matrix
array[1..N] var 0..N-1: d;          % degree sequence

% No loops
constraint
  forall(i in 1..N) (
    adj[i,i] = false
  );

% Symmetry of adjacency
constraint
  forall(i,j in 1..N where i < j) (
    adj[i,j] = adj[j,i]
  );

% Link degrees to adjacency
constraint
  forall(i in 1..N) (
    d[i] = sum(j in 1..N where j != i)( bool2int(adj[i,j]) )
  );

% Non‐increasing degree sequence
constraint
  forall(i in 1..N-1)(
    d[i] >= d[i+1]
  );

% Each degree is >0 and a multiple of 3
constraint
  forall(i in 1..N)(
    d[i] >= 3 /\ d[i] mod 3 = 0
  );

% Sum of degrees ≡ 0 (mod 12)
constraint
  (sum(i in 1..N)(d[i])) mod 12 = 0;

% Diamond‐free: any 4 vertices have at most 4 edges among them
constraint
  forall(a,b,c,e in 1..N where a < b /\ b < c /\ c < e) (
    sum([
      bool2int(adj[x,y])
      | x,y in {a,b,c,e} where x < y
    ]) <= 4
  );

solve satisfy;

% Output the adjacency matrix as JSON
output [
  "{",
    "\"matrix\": [",
      join(", ",
        [ "[" ++
            join(", ",
              [ show(bool2int(adj[i,j])) | j in 1..N ]
            )
          ++ "]"
        | i in 1..N
        ]
      ),
    "]",
  "}"
];
```

