% Graceful Graph Labelling for a graph with m edges and n nodes.
% Nodes are labeled with distinct values in 0..m.
% Each edge is labeled with the absolute difference of its endpoint labels.
% All edge labels must be distinct.

int: m = 16;  % number of edges
int: n = 8;   % number of nodes

% Graph edges given 0-based; convert to 1-based for MiniZinc arrays
array[1..m] of int: u = [1,1,1,2,2,3, 5,5,5,6,6,7, 1,2,3,4];
array[1..m] of int: v = [2,3,4,3,4,4, 6,7,8,7,8,8, 5,6,7,8];

% Node labels: each f[i] in 0..m, all different
array[1..n] of var 0..m: f;
constraint alldifferent(f);

% Edge labels: d[i] = |f[u[i]] - f[v[i]]|, must be in 1..m, all different
array[1..m] of var 1..m: d;
constraint forall(i in 1..m)(d[i] = abs(f[u[i]] - f[v[i]]));
constraint alldifferent(d);

% Symmetry‐breaking: you may fix one node label, e.g., f[1] = 0
constraint f[1] = 0;

solve satisfy;

output [
    "{",
    join(",", [
      "\"nodes\": [" ++ join(",", [show(f[i]) | i in 1..n]) ++ "]",
      "\"edges\": [" ++ join(",", [show(d[i]) | i in 1..m]) ++ "]"
    ]),
    "}"
];
```

