```minizinc
% 2cc Hadamard matrix Legendre pairs CSP in MiniZinc

% Input parameter: odd positive integer l
int: l;
% Compute m = (l - 1) / 2
int: m = (l - 1) div 2;

% Domain for sequence entries: either -1 or +1
set of int: S = {-1, 1};

% Variables: two sequences a[1..l], b[1..l]
array[1..l] of var S: a;
array[1..l] of var S: b;

% Linear constraints: each sequence sums to 1
constraint
  sum(i in 1..l)(a[i]) = 1 /\
  sum(i in 1..l)(b[i]) = 1;

% Quadratic constraints: for each shift s = 1..m,
% PAF(A,s) + PAF(B,s) = -2, where indices wrap around mod l
constraint
  forall(s in 1..m) (
    let {
      % helper function for wrapping index
      function int: idx = function(var int: i, int: shift) =
        ((i + shift - 1) mod l) + 1
    } in
      sum(i in 1..l)( a[i] * a[idx(i, s)] )
    + sum(i in 1..l)( b[i] * b[idx(i, s)] )
    = -2
  );

solve satisfy;

% Output the two sequences as JSON
output [
  "{",
    "\"a\": [" ++ join(",", [show(a[i]) | i in 1..l]) ++ "],",
    "\"b\": [" ++ join(",", [show(b[i]) | i in 1..l]) ++ "]",
  "}"
];
```

