% Logic puzzle: Four friends (Debra=0, Janet=1, Hugh=2, Rick=3)
% Surnames: 1=Baxter, 2=Lemon, 3=Malone, 4=Fleet
% Allergies: 1=eggs,   2=mold,  3=nuts,   4=ragweed

include "globals.mzn";

int: N = 4;
set of int: FRIENDS = 0..3;
set of int: SNAME = 1..4;
set of int: ALLER = 1..4;

array[FRIENDS] of var SNAME: surname;
array[FRIENDS] of var ALLER: allergy;

% All surnames and allergies are distinct
constraint all_different([surname[i] | i in FRIENDS]);
constraint all_different([allergy[i] | i in FRIENDS]);

% Rick is not allergic to mold
constraint allergy[3] != 2;

% Baxter is allergic to eggs
constraint forall(i in FRIENDS)(surname[i] = 1 -> allergy[i] = 1);

% Hugh is neither surnamed Lemon nor Fleet
constraint surname[2] != 2 /\ surname[2] != 4;

% Debra is allergic to ragweed
constraint allergy[0] = 4;

% Janet (who isn't Lemon) is neither allergic to eggs nor to mold
constraint surname[1] != 2;
constraint allergy[1] != 1 /\ allergy[1] != 2;

solve satisfy;

% Names for output
array[SNAME] of string: famnames = ["Baxter","Lemon","Malone","Fleet"];
array[ALLER] of string: allername = ["eggs","mold","nuts","ragweed"];

