% Given pair‐sums of five bales in sorted order:
int: N = 5;
int: M = N*(N-1) div 2;
array[1..M] of int: s = [80,82,83,84,85,86,87,88,90,91];

% Decision variables: weights of the five bales, in ascending order
array[1..N] of var 0..100: x;
constraint forall(i in 1..N-1)(x[i] < x[i+1]);

% Precomputed indices of the 10 distinct pairs (i<j)
array[1..M] of int: pair_i = [1,1,1,1, 2,2,2, 3,3, 4];
array[1..M] of int: pair_j = [2,3,4,5, 3,4,5, 4,5, 5];

% Compute the sums for each pair
array[1..M] of var 0..200: sums;
constraint
  forall(k in 1..M) (
    sums[k] = x[pair_i[k]] + x[pair_j[k]]
  );

% Enforce that the multiset of computed sums equals the given multiset s
% Since both are of size M and all given sums are distinct, it's enough to say:
constraint
  forall(v in s) (
    sum(k in 1..M)(bool2int(sums[k] = v)) = 1
  );

% Symmetry‐breaking: the smallest sum is x1+x2, the largest is x4+x5
constraint x[1] + x[2] = s[1];
constraint x[N-1] + x[N] = s[M];

solve satisfy;

output [
  "{",
    "\"bales\": [" ++ join(",", [show(x[i]) | i in 1..N]) ++ "]",
  "}"
];
```

