% Nontransitive dice for Rock-Paper-Scissors-Lizard-Spock
% 5 dice, each with 6 faces, values in 1..20

int: num_dice = 5;
int: num_faces = 6;
int: max_face = 20;

array[1..num_dice, 1..num_faces] of var 1..max_face: dice;

% enforce non-decreasing faces on each die to break symmetries
constraint
  forall(d in 1..num_dice) (
    increasing([ dice[d,f] | f in 1..num_faces ])
  );

% The 10 "beats" relations: (winner, loser)
int: num_beats = 10;
array[1..num_beats, 1..2] of int: beats = 
  [| 1,3    % Rock (1) beats Scissors (3)
   | 1,4    % Rock (1) beats Lizard   (4)
   | 2,1    % Paper(2) beats Rock     (1)
   | 2,5    % Paper(2) beats Spock    (5)
   | 3,2    % Scissors(3) beats Paper (2)
   | 3,4    % Scissors(3) beats Lizard (4)
   | 4,2    % Lizard (4) beats Paper  (2)
   | 4,5    % Lizard (4) beats Spock  (5)
   | 5,1    % Spock  (5) beats Rock   (1)
   | 5,3    % Spock  (5) beats Scissors(3)
  |];

% For each beat relation, count wins and losses
array[1..num_beats] of var 0..(num_faces*num_faces): wins;
array[1..num_beats] of var 0..(num_faces*num_faces): losses;

constraint
  forall(b in 1..num_beats) (
    let {
      int: u = beats[b,1],
      int: v = beats[b,2]
    } in
      wins[b]   = sum(i,j in 1..num_faces)( bool2int(dice[u,i] > dice[v,j]) ) /\
      losses[b] = sum(i,j in 1..num_faces)( bool2int(dice[v,i] > dice[u,j]) ) /\
      wins[b] > losses[b]
  );

solve satisfy;

output [
  "{",
    "\"dice\": [",
      join(",",
        [ "[" ++ join(",", [ show(dice[d,f]) | f in 1..num_faces ]) ++ "]"
          | d in 1..num_dice
        ]
      ),
    "]",
  "}"
];
```

