int: nWeights = 4;
int: maxW = 40;
array[1..nWeights] of var 1..maxW: weights;

% Symmetry‐breaking: enforce strictly increasing weights
constraint forall(i, j in 1..nWeights where i < j)(
    weights[i] < weights[j]
);

% The four pieces sum to 40
constraint sum(i in 1..nWeights)(weights[i]) = maxW;

% For each target weight t in 1..40, we choose for each piece i
% a placement x[t,i] in {-1,0,1}:
%   -1 means the piece is placed on the object's side,
%    0 means unused,
%   +1 means placed on the opposite pan.
% The balance equation is sum(x[t,i]*weights[i]) = t.
array[1..maxW, 1..nWeights] of var -1..1: x;

constraint
  forall(t in 1..maxW)(
    sum(i in 1..nWeights)(x[t,i] * weights[i]) = t
  );

solve satisfy;

output [
  "{" ++
    "\"weights\":[" ++
      join(",", [ show(weights[i]) | i in 1..nWeights ]) ++
    "]" ++
  "}"
];
```

