enum DEV = {A, B, C, D, E, F, G, H};
int: num_positions = card(DEV);

% Position in the rack (1..8) for each device
array[DEV] of var 1..num_positions: pos;

% Define the required connections: from, to, and number of parallel cables
int: num_connections = 8;
array[1..num_connections] of DEV: conn_from = [A, A, B, C, C, C, D, G];
array[1..num_connections] of DEV: conn_to   = [H, E, F, G, D, E, H, H];
array[1..num_connections] of int: cables =    [1, 2, 4, 1, 1, 1, 3, 1];

