var int: total_length = 
    sum(i in 1..num_connections)(
      cables[i] * abs(pos[conn_from[i]] - pos[conn_to[i]])
    );

% All devices occupy distinct rack units
constraint all_different([pos[d] | d in DEV]);

solve minimize total_length;

output [
  "{",
    join(",", [
      "\"" ++ "final_sum" ++ "\": " ++ show(total_length)
    ]),
  "}"
];
