include "globals.mzn";

% problem size
int: n = 5;
int: N2 = n * n;

% row[k], col[k]: position of number k in the grid
array[1..N2] of var 1..n: row;
array[1..N2] of var 1..n: col;

% pos[k]: linearized position = (row[k]-1)*n + col[k]
array[1..N2] of var 1..N2: pos;

% x_flat[p]: the number placed at linear index p (row‐major)
array[1..N2] of var 1..N2: x_flat;

% link x_flat and pos as inverses:
constraint inverse(x_flat, pos);

% define pos in terms of row, col
constraint forall(k in 1..N2) (
    pos[k] = (row[k] - 1) * n + col[k]
);

% all positions must be distinct
constraint all_different(pos);

% movement constraints for consecutive numbers
constraint forall(k in 1..N2-1) (
    % Type I: horizontal or vertical exactly 3 away
    (abs(row[k+1] - row[k]) = 3 /\ col[k+1] = col[k])
    \/
    (abs(col[k+1] - col[k]) = 3 /\ row[k+1] = row[k])
    \/
    % Type II: diagonal exactly 2 away
    (abs(row[k+1] - row[k]) = 2 /\ abs(col[k+1] - col[k]) = 2)
);

solve satisfy;

% output the grid as a JSON array of arrays
output [
  "{",
    "\"x\": [",
      join(
        ",",
        [ "[" ++ join(",", [ show(x_flat[(i-1)*n + j]) | j in 1..n ]) ++ "]"
          | i in 1..n
        ]
      ),
    "]",
  "}"
];
```

