% We label persons as 0->X, 1->Y, 2->Z
set of int: PERSONS = 0..2;
% Nationalities 0->American, 1->English, 2->French
set of int: NATION = 0..2;

% x,y,z = nationality of X,Y,Z respectively
var NATION: x;
var NATION: y;
var NATION: z;
array[PERSONS] of var NATION: personNat = [ x, y, z ];

% american,english,french = the person who has that nationality
var PERSONS: american;
var PERSONS: english;
var PERSONS: french;

% Passing relation: each person passes to exactly one other (a 3‐cycle)
array[PERSONS] of var PERSONS: pass_to;

% All persons have different nationalities
constraint all_different([x, y, z]);

% Each nationality is assigned to exactly one person
constraint all_different([american, english, french]);

% Link personNat and nationality‐holders:
% personNat[p] = c  <=>  if person p has code c as nationality
constraint element(american, personNat, 0);  % american‐holder has code 0
constraint element(english, personNat, 1);  % english‐holder has code 1
constraint element(french,  personNat, 2);  % french‐holder has code 2

% Derangement on 3 persons → a single 3‐cycle (no fixed points)
constraint all_different(pass_to);
constraint forall(p in PERSONS)( pass_to[p] != p );

% Clues:
% Y (1) passed to the American
constraint pass_to[1] = american;
% X (0) passed to P, and P passed to the Frenchwoman
% i.e. pass_to[ pass_to[0] ] = french
constraint pass_to[ pass_to[0] ] = french;

solve satisfy;

output [
