% Input data
int: num_moves;
array[1..num_coins] of int: init;  % 0=head, 1=tail

% Derive number of coins
int: num_coins = length(init);

% Decision variables: which coin to flip at each move
array[1..num_moves] of var 1..num_coins: steps;

% States of the coins after each move (and initial state at index 0)
array[0..num_moves, 1..num_coins] of var 0..1: state;

% Initial state
constraint
  forall(c in 1..num_coins) (
    state[0,c] = init[c]
  );

% Transition: flip the selected coin at each step
constraint
  forall(m in 1..num_moves, c in 1..num_coins) (
    state[m,c] = if steps[m] = c then 1 - state[m-1,c]
                  else state[m-1,c]
  );

% Final configuration must be all heads (0) or all tails (1)
constraint
  forall(c1, c2 in 1..num_coins) (
    state[num_moves, c1] = state[num_moves, c2]
  );

solve satisfy;

% Output the sequence of flips as JSON
output [
  "{",
    "\"steps\": [" ++
      join(",", [ show(steps[m]) | m in 1..num_moves ]) ++
    "]",
  "}"
];
```

