% Given a target number of beers, find the closest combination
% of 7-packs and 13-packs that meets or exceeds the target.

int: target = 20;

% Upper bounds on number of packs (safe overestimate)
int: maxX = ceil(target/7.0) + 1;
int: maxY = ceil(target/13.0) + 1;

var 0..maxX: x;  % number of 7-packs
var 0..maxY: y;  % number of 13-packs

var int: total = 7*x + 13*y;
constraint total >= target;

var int: overshoot = total - target;
solve minimize overshoot;

% Output JSON with counts of 7-packs and 13-packs
output [
    "{\"counts\": [" ++ show(x) ++ "," ++ show(y) ++ "]}"
];
```

